-- ============================================================
-- Retiros/Pastos do Grupo Ricci — seed completo
-- ============================================================

-- Adicionar coluna codigo se não existir
ALTER TABLE subdivisoes ADD COLUMN IF NOT EXISTS codigo TEXT;
ALTER TABLE subdivisoes ADD COLUMN IF NOT EXISTS codigo_normalizado TEXT;

-- Limpar registros antigos de seed (manter apenas os reais)
DELETE FROM subdivisoes WHERE codigo IS NULL AND nome IN ('Pasto 01','Pasto 02','Confinamento','Piquete 1','Piquete 2');

-- Inserir retiros reais

-- Verificar resultado
SELECT f.nome as fazenda, COUNT(s.id) as qtd_retiros FROM subdivisoes s JOIN fazendas f ON f.id = s.fazenda_id WHERE s.ativo = true GROUP BY f.nome ORDER BY f.nome;